from pathlib import Path
import base64
import sys

CONTEXT = Path("components/portal/portal-context-panel.tsx")
NEW_COMPONENT = Path("components/portal/forum-navigation-context.tsx")

def fail(message):
    print(f"ERROR: {message}")
    print("No files were changed.")
    sys.exit(1)

if not CONTEXT.exists():
    fail(f"{CONTEXT} not found. Run this script from the repository root.")

if NEW_COMPONENT.exists():
    fail(f"{NEW_COMPONENT} already exists. This patch expects the current pushed master before this feature.")

text = CONTEXT.read_text(encoding="utf-8")

def replace_once(old, new, label):
    global text
    if text.count(old) != 1:
        fail(f"{label} was not found exactly once.")
    text = text.replace(old, new, 1)

replace_once('import { ForumSectionActivityContext } from "@/components/portal/forum-section-activity-context";', 'import {\n  ForumSectionsNavigatorContext,\n  ForumTopicsNavigatorContext,\n  ForumTopicNavigatorContext,\n} from "@/components/portal/forum-navigation-context";', "Forum context import")
replace_once('  if (pathname === "/forum") {\n    return <ForumOverviewContext />;\n  }', '  if (pathname === "/forum") {\n    return <ForumSectionsNavigatorContext />;\n  }', "Forum overview route")
replace_once('  if (forumTopicMatch) {\n    return (\n      <ForumTopicContext\n        sectionSlug={decodeURIComponent(\n          forumTopicMatch[1],\n        )}\n        topicSlug={decodeURIComponent(\n          forumTopicMatch[2],\n        )}\n        quickReplyPostId={\n          searchParams.get(\n            "quickReply",\n          )\n        }\n      />\n    );\n  }', '  if (forumTopicMatch) {\n    return (\n      <ForumTopicNavigatorContext\n        sectionSlug={decodeURIComponent(\n          forumTopicMatch[1],\n        )}\n        topicSlug={decodeURIComponent(\n          forumTopicMatch[2],\n        )}\n      />\n    );\n  }', "Forum topic route")
replace_once('  if (forumSectionMatch) {\n  return (\n    <ForumSectionActivityContext\n      sectionSlug={decodeURIComponent(\n        forumSectionMatch[1],\n      )}\n    />\n  );\n}', '  if (forumSectionMatch) {\n    return (\n      <ForumTopicsNavigatorContext\n        sectionSlug={decodeURIComponent(\n          forumSectionMatch[1],\n        )}\n      />\n    );\n  }', "Forum section route")

# Validate the existing main topic page anchors that the navigator depends on.
TOPIC_PAGE = Path("app/(portal)/forum/[sectionSlug]/[topicSlug]/page.tsx")
TOPIC_POST = Path("components/forum/topic-post.tsx")
REPLY_FORM = Path("components/forum/topic-reply-form.tsx")

for path in (TOPIC_PAGE, TOPIC_POST, REPLY_FORM):
    if not path.exists():
        fail(f"{path} not found.")

if 'id={`post-${post.id}`}' not in TOPIC_POST.read_text(encoding="utf-8"):
    fail("Forum post jump anchors are missing.")

reply_text = REPLY_FORM.read_text(encoding="utf-8")
if 'id="reply"' not in reply_text or 'id="forum-reply-body"' not in reply_text:
    fail("Main forum reply editor anchors are missing.")

# All validation finished before writes.
CONTEXT.write_text(text, encoding="utf-8")
NEW_COMPONENT.parent.mkdir(parents=True, exist_ok=True)
NEW_COMPONENT.write_text(
    base64.b64decode('').decode("utf-8"),
    encoding="utf-8",
)

print("Forum context sidebar rebuilt.")
print("")
print("Modified:")
print(f" - {CONTEXT}")
print("Created:")
print(f" - {NEW_COMPONENT}")
print("")
print("/forum: live section search + jump to section.")
print("/forum/[section]: live topic search + jump to topic.")
print("/forum/[section]/[topic]: always-open Quick Reply, live reply search, jump to reply, and Jump to main reply editor.")
print("The old section activity feed is no longer routed.")
print("Existing forum posting action and permissions remain authoritative.")
print("No backup files were created.")
